    catch (IllegalArgumentException ex) {
        this.onlyError = true;
        cefCallback.Continue();
        return true;
    }
    this.task = new ClientTaskGetFile(uuid, fileStr);
    boolean doContinue = Client.getInstance().addTask(this.task);
